window.__finlexDocLoaded(10197,{"id":10197,"articles":[{"id":1000819,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Governs definition and FVTPL accounting for freestanding/embedded derivatives, own-equity scope exceptions (ASC 815-40), and fair value, cash flow, and net investment hedge accounting (including Portfolio Layer Method, ASU 2022-01).","seq":0},{"id":1000820,"no":"ASC 815-10 / 815-20 / 815-40","heading":"Derivative Definition, Hedge Accounting & ASC 815-40 Equity Indexation","text":"• Derivative Characteristics (ASC 815-10-15-83): Underlying + notional/payment provision, little or no initial net investment, AND net settlement (including readily convertible to cash).\n• Hedge Accounting (ASC 815-20): Requires 'highly effective' (80%–125% corridor in practice) at inception and ongoing; Fair Value Hedges (incl. Portfolio Layer Method for closed prepayable pools), Cash Flow Hedges (entire change in hedging instrument recorded in OCI and reclassified when hedged item affects P&L), and Net Investment Hedges.\n• Contracts in Entity's Own Equity (ASC 815-40): 2-step indexation & equity-classification framework (critical for SPAC warrants and convertible features).","seq":1},{"id":1000821,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Hedge Effectiveness: IFRS 9 eliminated the rigid 80%–125% quantitative bright line in favor of an economic relationship principle; ASC 815 retains 'highly effective' (though ASU 2017-12 allows qualitative ongoing assessments and eliminated separate ineffectiveness measurement for cash flow hedges).","seq":2},{"id":1000822,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
